240	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
241	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
242	
243	    /**
244	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
245	     * code are kept when present; otherwise country code '+61' is assumed and a single
246	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
247	     * stripped. The result must be a '+' followed by 8 to 15 digits.
248	     * Returns {@code null} when the number cannot form a valid E.164 value.
249	     */
250	    private static String normalizeTelephone(String telephone) {
251	        if (telephone == null) {
252	            return null;
253	        }
254	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
255	        String e164;
256	        if (cleaned.startsWith("+")) {
257	            e164 = cleaned;
258	        } else {
259	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
260	            e164 = "+61" + national;
261	        }
262	        return E164_PATTERN.matcher(e164).matches() ? e164 : null;
263	    }
264	
265	    /**
266	     * Build the customer code '<LAST3>-<NNNN>': LAST3 is the upper-cased first three letters
267	     * of {@code lastName} and NNNN is a global 4-digit zero-padded sequence equal to one more
268	     * than the current number of owners (e.g. 'SMI-0007').
269	     */
270	    private String generateCustomerCode(String lastName) {
271	        String letters = lastName.replaceAll("[^\\p{L}]", "");
272	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
273	        int sequence = this.clinicService.findAllOwners().size() + 1;
274	        return String.format("%s-%04d", last3, sequence);
275	    }
276	
277	    /** Whether any existing owner already uses the given (E.164) telephone number. */
278	    private boolean isTelephoneInUse(String telephone) {
279	        return this.clinicService.findAllOwners().stream()
280	            .map(Owner::getTelephone)
281	            .filter(existing -> existing != null)
282	            .map(OwnerRestControllerV1::normalizeTelephone)
283	            .filter(existing -> existing != null)
284	            .anyMatch(telephone::equals);
285	    }
286	
287	    /**
288	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
289	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
290	     */
291	    private static String normalizeHouseholdField(String value) {
292	        if (value == null) {
293	            return "";
294	        }
295	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
296	    }
297	
298	    /**
299	     * Whether any existing owner already shares the same household as {@code owner}, i.e. has the
300	     * same last name AND the same address compared case-insensitively with collapsed whitespace.
301	     */
302	    private boolean isHouseholdInUse(Owner owner) {
303	        String lastName = normalizeHouseholdField(owner.getLastName());
304	        String address = normalizeHouseholdField(owner.getAddress());
305	        return this.clinicService.findAllOwners().stream()
306	            .anyMatch(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
307	                && normalizeHouseholdField(existing.getAddress()).equals(address));
308	    }
309	}
